/**
 * Litos brand assets. One source of truth, one artwork.
 *
 *   node scripts/generate-brand-assets.mjs
 *
 * The mark is "The Stack": four bars tapering to a solid block, centred on the
 * axis and sheared 6 degrees. It is ALWAYS black on a plain white ground. There
 * is no reversed, tinted, or accent-coloured variant, by design.
 *
 * Everything under public/brand/ and app/icon.png is generated by this script.
 * Do not hand-edit those files; change MARK_PATH here and re-run.
 */
import sharp from 'sharp';
import { writeFile, mkdir } from 'node:fs/promises';
import { join } from 'node:path';

// Regular master, 100x100 grid. Widths step 7.2, gaps constant, block breaks
// only the height. Centred on x=50, sheared 6deg.
const MARK_PATH =
  'M32.81 8 L76.01 8 L75.17 16 L31.97 16 Z M27.53 24 L77.93 24 L77.09 32 L26.69 32 Z M22.25 40 L79.85 40 L79.01 48 L21.41 48 Z M16.97 56 L81.77 56 L80.93 64 L16.13 64 Z M11.69 72 L83.69 72 L81.59 92 L9.59 92 Z';

const markSvg = (size = 100) =>
  `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100" width="${size}" height="${size}">` +
  `<rect width="100" height="100" fill="#ffffff"/>` +
  `<path fill="#000000" d="${MARK_PATH}"/></svg>`;

const lockupSvg =
  `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 620 160" width="620" height="160" role="img" aria-labelledby="t">` +
  `<title id="t">Litos</title><rect width="620" height="160" fill="#ffffff"/>` +
  `<g transform="translate(24 26) scale(1.08)"><path fill="#000000" d="${MARK_PATH}"/></g>` +
  `<text x="186" y="103" fill="#000000" font-family="Helvetica Neue, Helvetica, Arial, sans-serif" ` +
  `font-size="60" font-weight="400" letter-spacing="12">LITOS</text></svg>`;

const OUT = 'public/brand';
await mkdir(OUT, { recursive: true });
await writeFile(join(OUT, 'litos-mark.svg'), markSvg() + '\n');
await writeFile(join(OUT, 'litos-logo.svg'), lockupSvg + '\n');

const buf = Buffer.from(markSvg(1024));
const render = (s) => sharp(buf, { density: 900 }).resize(s, s).png({ compressionLevel: 9 });

for (const s of [16, 32, 48, 64, 96, 128, 256, 512]) {
  await render(s).toFile(join(OUT, `litos-mark-${s}.png`));
}
for (const s of [128, 256, 512]) {
  await render(s).toFile(join(OUT, `litos-tile-${s}.png`));
}
await render(128).toFile(join(OUT, 'litos-store-icon-128.png'));
await render(512).toFile('app/icon.png');
await sharp(Buffer.from(lockupSvg), { density: 900 })
  .resize(1240, 320).png({ compressionLevel: 9 }).toFile(join(OUT, 'litos-logo@2x.png'));

console.log('brand assets generated from one artwork: black stack on white');
